describe('Logout from Side Menu - Signed In Customer', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should successfully log out from the side menu and return to login page', () => {
    // Login with standard user credentials
    cy.get('[data-testid="user-input"]').type('standard_user');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Verify successful login
    cy.url().should('include', '/inventory.');
    cy.get('[data-testid="inventory-page-title"]').should('be.visible');

    // Open the side menu
    cy.get('[data-testid="react-burger-menu-btn"]').click();

    // Verify side menu is open
    cy.get('[data-testid="side-menu"]').should('be.visible');
    cy.get('[data-testid="logout-sidebar-link"]').should('be.visible');

    // Click logout link
    cy.get('[data-testid="logout-sidebar-link"]').click();

    // Verify logout redirect
    cy.url().should('include', '/');
    cy.get('[data-testid="login-button"]').should('be.visible');
    cy.get('[data-testid="user-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
  });

  it('should handle logout when side menu is not visible', () => {
    // Login with standard user credentials
    cy.get('[data-testid="user-input"]').type('standard_user');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Verify successful login
    cy.url().should('include', '/inventory.');
    cy.get('[data-testid="inventory-page-title"]').should('be.visible');

    // Attempt to click logout without opening side menu
    cy.get('[data-testid="logout-sidebar-link"]').should('not.exist');

    // Open side menu
    cy.get('[data-testid="react-burger-menu-btn"]').click();

    // Verify side menu is open
    cy.get('[data-testid="side-menu"]').should('be.visible');

    // Click logout link
    cy.get('[data-testid="logout-sidebar-link"]').click();

    // Verify logout redirect
    cy.url().should('include', '/');
    cy.get('[data-testid="login-button"]').should('be.visible');
  });
});
